import filtersIcon from '@jetbrains/icons/filters.svg'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import {useBuildId} from '../../../hooks/routes'
import {usePermission} from '../../../hooks/usePermission'
import {getBuildHref} from '../../../routes'
import {
  getBuild,
  getBuildType,
  getIsSakuraUI,
  makeGetClassicUILinkWithBranch,
} from '../../../selectors'
import {
  ClassicUIBuildTabNamesEnum,
  BuildPageTabNamesEnum,
  Permission,
  stringifyId,
} from '../../../types'
import RouterLinkWrapper from '../RouterLinkWrapper/RouterLinkWrapper'

import styles from './CustomizedBuildNote.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

export type CustomizedBuildNoteProps = {
  embedded?: boolean
  withIcon?: boolean
  className?: string
}

function CustomizedBuildSection({embedded, withIcon = false, className}: CustomizedBuildNoteProps) {
  const buildId = useBuildId()
  const buildTypeId = useAppSelector(state => getBuild(state, buildId)?.buildType)
  const isCustomizedParams = useAppSelector(
    state => getBuild(state, buildId)?.customization?.parameters || false,
  )
  const isCustomizedChanges = useAppSelector(
    state => getBuild(state, buildId)?.customization?.changes || false,
  )
  const isCustomizedArtifacts = useAppSelector(
    state => getBuild(state, buildId)?.customization?.artifactDependencies || false,
  )
  const isCustomizedDependencies = useAppSelector(
    state => getBuild(state, buildId)?.customization?.dependencies || false,
  )
  const projectId = useAppSelector(state => getBuildType(state, buildTypeId)?.projectId)
  const showParametersLink = usePermission(Permission.VIEW_BUILD_RUNTIME_DATA, projectId)
  const isSakuraUI = useAppSelector(getIsSakuraUI)
  const getClassicUIParametersLink = React.useMemo(
    () =>
      makeGetClassicUILinkWithBranch(
        {
          buildId,
          buildTypeId,
        },
        null,
        {
          tab: stringifyId(ClassicUIBuildTabNamesEnum.buildParameters),
          onlyModified: 'true',
        },
      ),
    [buildId, buildTypeId],
  )
  const classicUIParametersLink = useAppSelector(getClassicUIParametersLink)
  const getClassicUIChangesLink = React.useMemo(
    () =>
      makeGetClassicUILinkWithBranch(
        {
          buildId,
          buildTypeId,
        },
        null,
        {
          tab: stringifyId(ClassicUIBuildTabNamesEnum.buildChangesDiv),
        },
      ),
    [buildId, buildTypeId],
  )
  const classicUIChangesLink = useAppSelector(getClassicUIChangesLink)
  const getClassicUIDependenciesLink = React.useMemo(
    () =>
      makeGetClassicUILinkWithBranch(
        {
          buildId,
          buildTypeId,
        },
        null,
        {
          tab: stringifyId(ClassicUIBuildTabNamesEnum.dependencies),
          depsTab: 'downloadedArtifacts',
        },
      ),
    [buildId, buildTypeId],
  )
  const classicUIDependenciesLink = useAppSelector(getClassicUIDependenciesLink)
  const links = React.useMemo(
    () => ({
      parameters:
        isCustomizedParams && buildId != null
          ? {
              classic: classicUIParametersLink,
              sakura: `${getBuildHref(buildId, buildTypeId)}?buildTab=${stringifyId(
                BuildPageTabNamesEnum.buildParameters,
              )}&onlyModified=true`,
            }
          : null,
      changes:
        isCustomizedChanges && buildId != null
          ? {
              classic: classicUIChangesLink,
              sakura: `${getBuildHref(buildId, buildTypeId)}?buildTab=${stringifyId(
                BuildPageTabNamesEnum.CHANGES,
              )}`,
            }
          : null,
      artifactDependencies:
        isCustomizedArtifacts && buildId != null
          ? {
              classic: classicUIDependenciesLink,
              sakura: `${getBuildHref(buildId, buildTypeId)}?buildTab=${stringifyId(
                BuildPageTabNamesEnum.DEPENDENCIES,
              )}&type=downloaded-artifacts`,
            }
          : null,
      dependencies: isCustomizedDependencies ? true : null,
    }),
    [
      buildId,
      buildTypeId,
      isCustomizedArtifacts,
      isCustomizedDependencies,
      isCustomizedChanges,
      isCustomizedParams,
      classicUIChangesLink,
      classicUIDependenciesLink,
      classicUIParametersLink,
    ],
  )
  const toRender = React.useMemo(() => {
    const result = []

    if (links.dependencies != null) {
      result.push(<span key={'dependencies'}>{`dependencies`}</span>)
    }

    if (links.parameters != null) {
      const buildParametersPart = showParametersLink ? (
        <RouterLinkWrapper>
          <Link
            key={'build-parameters'}
            href={isSakuraUI ? links.parameters.sakura : links.parameters.classic}
          >
            {'parameters'}
          </Link>
        </RouterLinkWrapper>
      ) : (
        <span key={'build-parameters'}>{'parameters'}</span>
      )
      result.push(buildParametersPart)
    }

    if (links.changes != null) {
      result.push(
        <RouterLinkWrapper>
          <Link key={'revisions'} href={isSakuraUI ? links.changes.sakura : links.changes.classic}>
            {'changes'}
          </Link>
        </RouterLinkWrapper>,
      )
    }

    if (links.artifactDependencies != null) {
      result.push(
        <RouterLinkWrapper>
          <Link
            key={'artifact-dependencies'}
            href={
              isSakuraUI ? links.artifactDependencies.sakura : links.artifactDependencies.classic
            }
          >{`artifact dependencies`}</Link>
        </RouterLinkWrapper>,
      )
    }

    const initialLength = result.length

    if (result.length > 1) {
      result.splice(result.length - 1, 0, <span key={'and'}>{' and '}</span>)

      for (let i = initialLength - 2; i >= 1; i--) {
        result.splice(i, 0, <span key={i}>{', '}</span>)
      }
    }

    if (result.length) {
      result.unshift('Build ')
    }

    return result
  }, [
    isSakuraUI,
    links.changes,
    links.artifactDependencies,
    links.dependencies,
    links.parameters,
    showParametersLink,
  ])

  if (
    !isCustomizedParams &&
    !isCustomizedChanges &&
    !isCustomizedArtifacts &&
    !isCustomizedDependencies
  ) {
    return null
  }

  return (
    <div className={classNames(styles.container, className, embedded === true && styles.embedded)}>
      {withIcon === true ? <SvgIcon className={styles.icon} icon={filtersIcon} /> : null}
      {toRender}
      {' have been customized'}
    </div>
  )
}

export default React.memo(CustomizedBuildSection)
